+            }
+        }
+        /* Verify decompressed size matches header */
+        if (out_pos != expected_size) {
+            goto fail;
+        }
+    } else {
+        goto fail;
+    }
+
+    /* Stage 3: Integrity verification */
+    checksum = compressed_data[data_size - 1];
+    sum = 0;
+    for (i = 0; i < expected_size; i++) {
+        sum += ctx->temp_buffer[i];
+    }
+    if ((sum & 0xFF) != checksum) {
+        goto fail;
+    }
+
+    return 0;
+
+fail:
+    if (locally_allocated) {
+        free(ctx->temp_buffer);
+        ctx->temp_buffer = NULL;
+        ctx->buffer_size = 0;
+    }
+    return -1;
+}

